// src/hooks/useSearchUsers.js - VERSÃO CORRIGIDA
import { useEffect, useState } from "react";
import { db } from "../js/firebaseConfig";
import { collection, getDocs } from "firebase/firestore";

export default function useSearchUsers() {
    const [allUsers, setAllUsers] = useState([]);
    const [search, setSearch] = useState("");

    useEffect(() => {
        const loadUsers = async () => {
            try {
                const snap = await getDocs(collection(db, "users"));
                const usersData = snap.docs.map(d => ({ 
                    id: d.id, 
                    ...d.data() 
                }));

                // ✅ Filtra usuários inválidos e garante campos obrigatórios
                const validUsers = usersData.filter(user => 
                    user.id && (user.email || user.nome) // Pelo menos um identificador
                ).map(user => ({
                    id: user.id,
                    nome: user.nome || user.email?.split('@')[0] || "Usuário",
                    email: user.email || "",
                    avatarUrl: user.avatarUrl || "",
                    online: user.online || false
                }));

                setAllUsers(validUsers);
                console.log("✅ Usuários carregados:", validUsers.length);
            } catch (error) {
                console.error("Erro ao carregar usuários:", error);
                setAllUsers([]);
            }
        };
        loadUsers();
    }, []);

    const searchUsers = (text) => {
        setSearch(text.toLowerCase());
    };

    // ✅ CORREÇÃO: Verifica se os campos existem antes de usar toLowerCase()
    const filtered = allUsers.filter(u => {
        const email = u.email || "";
        const nome = u.nome || "";
        return email.toLowerCase().includes(search) || 
               nome.toLowerCase().includes(search);
    });

    return {
        allUsers,
        filtered,
        searchUsers,
        search
    };
}
